/* eslint-env node */
// Phase 5: builds AVIF (480/800/1200 px) and a JPEG fallback from the original artwork.
// The originals are never touched. Output goes to public/img/ (git-ignored, regenerated by `npm run images`,
// and by prebuild/predev when something is missing) and src/content/image-manifest.json (committed).
// Usage: node scripts/optimize-images.mjs [lote ...]     (default: every lote in LOTES)
// A lote is a list of modules; every image they import (import x from './a.jpg') is processed.
import { readFileSync, writeFileSync, mkdirSync, existsSync, statSync } from 'node:fs';
import { dirname, resolve, relative, basename, extname } from 'node:path';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT_DIR = resolve(ROOT, 'public/img');
const MANIFEST = resolve(ROOT, 'src/content/image-manifest.json');
const WIDTHS = [480, 800, 1200];
const FALLBACK_WIDTH = 800;

const LOTES = {
  home: [
    'src/objects/newPaintings.jsx',
    'src/components/AgendaSection.jsx',
  ],
};

const IMG_IMPORT = /import\s+\w+\s+from\s+['"]([^'"]+\.(?:jpe?g|png))['"]/gi;

const toKey = (abs) => '/' + relative(ROOT, abs).split('\\').join('/');
const slugOf = (key) =>
  key.replace(/^\/src\//, '').replace(/\.[^.]+$/, '').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase();

const lotes = process.argv.slice(2);
const names = lotes.length ? lotes : Object.keys(LOTES);
const files = new Set();
for (const name of names) {
  if (!LOTES[name]) throw new Error(`Lote desconocido: ${name} (hay: ${Object.keys(LOTES).join(', ')})`);
  for (const mod of LOTES[name]) {
    const modPath = resolve(ROOT, mod);
    for (const m of readFileSync(modPath, 'utf8').matchAll(IMG_IMPORT)) files.add(resolve(dirname(modPath), m[1]));
  }
}

mkdirSync(OUT_DIR, { recursive: true });
mkdirSync(dirname(MANIFEST), { recursive: true });
const manifest = existsSync(MANIFEST) ? JSON.parse(readFileSync(MANIFEST, 'utf8')) : {};
const fmt = (n) => (n / 1024).toFixed(0) + ' KB';
let done = 0;
let skipped = 0;

for (const abs of [...files].sort()) {
  const key = toKey(abs);
  const slug = slugOf(key);
  const fbOut = (w) => resolve(OUT_DIR, `${slug}-${w}.jpg`);
  const known = manifest[key];
  if (known && existsSync(fbOut(known.fallback)) && statSync(fbOut(known.fallback)).mtimeMs >= statSync(abs).mtimeMs && known.widths.every((w) => existsSync(resolve(OUT_DIR, `${slug}-${w}.avif`)))) {
    skipped++;
    continue;
  }
  const source = sharp(abs).rotate(); // honor EXIF orientation, like the browser does
  const { width: w0, height: h0 } = await sharp(await source.clone().toBuffer()).metadata();
  const widths = [...new Set(WIDTHS.map((w) => Math.min(w, w0)))];
  const sizes = {};
  for (const w of widths) {
    const avif = await source.clone().resize({ width: w, withoutEnlargement: true })
      .avif({ quality: 55, effort: 4 }).toFile(resolve(OUT_DIR, `${slug}-${w}.avif`));
    sizes[w] = avif.size;
  }
  const fbWidth = Math.min(FALLBACK_WIDTH, w0);
  const jpg = await source.clone().resize({ width: fbWidth, withoutEnlargement: true })
    .jpeg({ quality: 82, mozjpeg: true }).toFile(fbOut(fbWidth));
  manifest[key] = { slug, width: w0, height: h0, widths, fallback: fbWidth };
  done++;
  console.log(`${basename(abs, extname(abs)).padEnd(28)} ${w0}x${h0}  orig ${fmt(statSync(abs).size)}  ` +
    widths.map((w) => `${w}: ${fmt(sizes[w])}`).join('  ') + `  jpg${fbWidth} ${fmt(jpg.size)}`);
}

const sorted = Object.fromEntries(Object.entries(manifest).sort(([a], [b]) => a.localeCompare(b)));
writeFileSync(MANIFEST, JSON.stringify(sorted, null, 2) + '\n');
console.log(`\n${done} procesadas, ${skipped} ya estaban al día → public/img/ · manifiesto: ${toKey(MANIFEST)}`);
